-- Emerald 24/7 Grocery: Sales, Inventory & Online Ordering Management System
-- Database for XAMPP (MySQL/MariaDB). Import via phpMyAdmin > Import.
-- Default password for all seeded users/customers: password

SET FOREIGN_KEY_CHECKS = 0;
DROP DATABASE IF EXISTS emerald_247;
CREATE DATABASE emerald_247 CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE emerald_247;
SET NAMES utf8mb4;

CREATE TABLE categories (
  category_id INT AUTO_INCREMENT PRIMARY KEY,
  category_name VARCHAR(100) NOT NULL UNIQUE,
  description VARCHAR(255),
  status ENUM('active','inactive') NOT NULL DEFAULT 'active',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE users (
  user_id INT AUTO_INCREMENT PRIMARY KEY,
  full_name VARCHAR(100) NOT NULL,
  email VARCHAR(120) NOT NULL UNIQUE,
  password VARCHAR(255) NOT NULL,
  role ENUM('admin','manager','cashier','inventory_clerk','purchasing') NOT NULL,
  contact_number VARCHAR(20),
  address VARCHAR(255),
  status ENUM('active','inactive') NOT NULL DEFAULT 'active',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE customers (
  customer_id INT AUTO_INCREMENT PRIMARY KEY,
  full_name VARCHAR(100) NOT NULL,
  email VARCHAR(120) NOT NULL UNIQUE,
  password VARCHAR(255) NOT NULL,
  contact_number VARCHAR(20),
  address VARCHAR(255),
  status ENUM('active','inactive') NOT NULL DEFAULT 'active',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE suppliers (
  supplier_id INT AUTO_INCREMENT PRIMARY KEY,
  supplier_name VARCHAR(150) NOT NULL,
  contact_person VARCHAR(100),
  contact_number VARCHAR(20),
  email VARCHAR(120),
  address VARCHAR(255),
  status ENUM('active','inactive') NOT NULL DEFAULT 'active',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE products (
  product_id INT AUTO_INCREMENT PRIMARY KEY,
  category_id INT NOT NULL,
  product_name VARCHAR(150) NOT NULL,
  description TEXT,
  price DECIMAL(10,2) NOT NULL,
  stock_qty INT NOT NULL DEFAULT 0,
  reorder_level INT NOT NULL DEFAULT 10,
  unit VARCHAR(20) NOT NULL DEFAULT 'pc',
  image VARCHAR(255),
  status ENUM('active','inactive') NOT NULL DEFAULT 'active',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (category_id) REFERENCES categories(category_id) ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE inventory (
  inventory_id INT AUTO_INCREMENT PRIMARY KEY,
  product_id INT NOT NULL UNIQUE,
  quantity INT NOT NULL DEFAULT 0,
  reorder_level INT NOT NULL DEFAULT 10,
  last_updated DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  FOREIGN KEY (product_id) REFERENCES products(product_id) ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE orders (
  order_id INT AUTO_INCREMENT PRIMARY KEY,
  customer_id INT NOT NULL,
  order_date DATETIME NOT NULL,
  order_status ENUM('pending','processing','out_for_delivery','delivered','completed','cancelled') NOT NULL DEFAULT 'pending',
  payment_method ENUM('COD','GCash','Maya','Credit Card') NOT NULL,
  total_amount DECIMAL(12,2) NOT NULL,
  delivery_address VARCHAR(255),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (customer_id) REFERENCES customers(customer_id) ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE order_items (
  order_item_id INT AUTO_INCREMENT PRIMARY KEY,
  order_id INT NOT NULL,
  product_id INT NOT NULL,
  quantity INT NOT NULL,
  unit_price DECIMAL(10,2) NOT NULL,
  total_price DECIMAL(12,2) NOT NULL,
  FOREIGN KEY (order_id) REFERENCES orders(order_id) ON DELETE CASCADE ON UPDATE CASCADE,
  FOREIGN KEY (product_id) REFERENCES products(product_id) ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE sales (
  sale_id INT AUTO_INCREMENT PRIMARY KEY,
  user_id INT NOT NULL,
  customer_id INT NULL,
  order_id INT NULL,
  sale_type ENUM('walk_in','online') NOT NULL,
  sale_date DATETIME NOT NULL,
  payment_method ENUM('Cash','GCash','Maya','Debit Card','Credit Card','COD') NOT NULL,
  total_amount DECIMAL(12,2) NOT NULL,
  status ENUM('completed','voided') NOT NULL DEFAULT 'completed',
  FOREIGN KEY (user_id) REFERENCES users(user_id) ON UPDATE CASCADE,
  FOREIGN KEY (customer_id) REFERENCES customers(customer_id) ON UPDATE CASCADE,
  FOREIGN KEY (order_id) REFERENCES orders(order_id) ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE sale_items (
  sale_item_id INT AUTO_INCREMENT PRIMARY KEY,
  sale_id INT NOT NULL,
  product_id INT NOT NULL,
  quantity INT NOT NULL,
  unit_price DECIMAL(10,2) NOT NULL,
  total_price DECIMAL(12,2) NOT NULL,
  FOREIGN KEY (sale_id) REFERENCES sales(sale_id) ON DELETE CASCADE ON UPDATE CASCADE,
  FOREIGN KEY (product_id) REFERENCES products(product_id) ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE payments (
  payment_id INT AUTO_INCREMENT PRIMARY KEY,
  reference_type ENUM('sale','order') NOT NULL,
  reference_id INT NOT NULL,
  payment_method ENUM('Cash','GCash','Maya','Debit Card','Credit Card','COD') NOT NULL,
  amount DECIMAL(12,2) NOT NULL,
  cash_tendered DECIMAL(12,2) NULL,
  change_amount DECIMAL(12,2) NULL,
  payment_date DATETIME NOT NULL,
  status ENUM('pending','paid','refunded','failed') NOT NULL DEFAULT 'pending',
  reference_number VARCHAR(50) NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_ref (reference_type, reference_id)
) ENGINE=InnoDB;

CREATE TABLE purchase_orders (
  po_id INT AUTO_INCREMENT PRIMARY KEY,
  supplier_id INT NOT NULL,
  po_date DATE NOT NULL,
  expected_date DATE,
  status ENUM('pending','partial','received','cancelled') NOT NULL DEFAULT 'pending',
  total_amount DECIMAL(12,2) NOT NULL,
  created_by INT NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (supplier_id) REFERENCES suppliers(supplier_id) ON UPDATE CASCADE,
  FOREIGN KEY (created_by) REFERENCES users(user_id) ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE purchase_order_items (
  po_item_id INT AUTO_INCREMENT PRIMARY KEY,
  po_id INT NOT NULL,
  product_id INT NOT NULL,
  quantity INT NOT NULL,
  unit_cost DECIMAL(10,2) NOT NULL,
  total_cost DECIMAL(12,2) NOT NULL,
  FOREIGN KEY (po_id) REFERENCES purchase_orders(po_id) ON DELETE CASCADE ON UPDATE CASCADE,
  FOREIGN KEY (product_id) REFERENCES products(product_id) ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE goods_receipts (
  receipt_id INT AUTO_INCREMENT PRIMARY KEY,
  po_id INT NOT NULL,
  received_by INT NOT NULL,
  received_date DATE NOT NULL,
  remarks VARCHAR(255),
  FOREIGN KEY (po_id) REFERENCES purchase_orders(po_id) ON UPDATE CASCADE,
  FOREIGN KEY (received_by) REFERENCES users(user_id) ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE goods_receipt_items (
  receipt_item_id INT AUTO_INCREMENT PRIMARY KEY,
  receipt_id INT NOT NULL,
  po_item_id INT NOT NULL,
  quantity_received INT NOT NULL,
  expiry_date DATE NULL,
  FOREIGN KEY (receipt_id) REFERENCES goods_receipts(receipt_id) ON DELETE CASCADE ON UPDATE CASCADE,
  FOREIGN KEY (po_item_id) REFERENCES purchase_order_items(po_item_id) ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE inventory_transactions (
  transaction_id INT AUTO_INCREMENT PRIMARY KEY,
  inventory_id INT NOT NULL,
  product_id INT NOT NULL,
  transaction_type ENUM('IN','OUT','ADJUSTMENT') NOT NULL,
  source_type ENUM('goods_receipt','sale','repackaging','stock_adjustment') NOT NULL,
  reference_id INT NOT NULL,
  quantity INT NOT NULL,
  remarks VARCHAR(255),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by INT NOT NULL,
  INDEX idx_src (source_type, reference_id),
  FOREIGN KEY (inventory_id) REFERENCES inventory(inventory_id) ON UPDATE CASCADE,
  FOREIGN KEY (product_id) REFERENCES products(product_id) ON UPDATE CASCADE,
  FOREIGN KEY (created_by) REFERENCES users(user_id) ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE repackaging (
  repackage_id INT AUTO_INCREMENT PRIMARY KEY,
  source_product_id INT NOT NULL,
  target_product_id INT NOT NULL,
  source_qty INT NOT NULL,
  target_qty INT NOT NULL,
  repackage_date DATE NOT NULL,
  repackaged_by INT NOT NULL,
  remarks VARCHAR(255),
  FOREIGN KEY (source_product_id) REFERENCES products(product_id) ON UPDATE CASCADE,
  FOREIGN KEY (target_product_id) REFERENCES products(product_id) ON UPDATE CASCADE,
  FOREIGN KEY (repackaged_by) REFERENCES users(user_id) ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE stock_adjustments (
  adjustment_id INT AUTO_INCREMENT PRIMARY KEY,
  inventory_id INT NOT NULL,
  adjustment_type ENUM('damaged','expired','lost','found','correction','returned') NOT NULL,
  quantity INT NOT NULL,
  reason VARCHAR(255),
  adjustment_date DATETIME NOT NULL,
  adjusted_by INT NOT NULL,
  FOREIGN KEY (inventory_id) REFERENCES inventory(inventory_id) ON UPDATE CASCADE,
  FOREIGN KEY (adjusted_by) REFERENCES users(user_id) ON UPDATE CASCADE
) ENGINE=InnoDB;


